subChunks.guidedPracticeStarterCode:
// Mock i18next for sandbox:
const translations = {
  en: {
    quests: {
      title: 'Quest Board',
      questCount_one: '{{count}} quest',
      questCount_other: '{{count}} quests',
      xpReward: 'Reward: {{amount}} XP',
      accept: 'Accept Quest',
    }
  },
  fr: {
    quests: {
      title: 'Tableau des Quêtes',
      questCount_one: '{{count}} quête',
      questCount_other: '{{count}} quêtes',
      xpReward: 'Récompense: {{amount}} XP',
      accept: 'Accepter la Quête',
    }
  },
};

import { useState } from 'react';

// Simple t() function for sandbox:
function createT(lang, ns) {
  return function t(key, options = {}) {
    const keys = translations[lang]?.[ns]?.[key];
    const pluralKey = options.count !== undefined
      ? (options.count === 1 ? `${key}_one` : `${key}_other`)
      : key;
    const template = translations[lang]?.[ns]?.[pluralKey] || key;
    return template.replace(/\{\{(\w+)\}\}/g, (_, k) => options[k] ?? `{{${k}}}`);
  };
}

export default function App() {
  const [lang, setLang] = useState('en');
  const t = createT(lang, 'quests');

  return (
    <div data-testid="app">
      {/* TODO: Language selector */}
      {/* TODO: QuestBoard using t() */}
      <h1 data-testid="title">{t('title')}</h1>
      <p data-testid="count-1">{t('questCount', { count: 1 })}</p>
      <p data-testid="count-5">{t('questCount', { count: 5 })}</p>
      <p data-testid="reward">{t('xpReward', { amount: 150 })}</p>
      <select
        data-testid="lang-selector"
        value={lang}
        onChange={e => setLang(e.target.value)}
      >
        <option value="en">English</option>
        <option value="fr">Français</option>
      </select>
    </div>
  );
}
